import { agent, s, workflow } from "rig";
import { readFileSync } from "node:fs";

type Pr = { number: number; title: string; body?: string };
type Node = { prs: number[]; label: string; summary: string };

const part = s.object({ label: s.string, summary: s.string, prs: s.array(s.int) });

// Agent role: decide whether a set of PRs is one coherent theme or split it in two along its strongest fault line.
const splitSet = agent({
  name: "splitSet",
  model: "small",
  input: s.object({ prs: s.string }),
  output: s.object({
    coherent: s.boolean,
    label: s.string,
    summary: s.string,
    a: part,
    b: part,
  }),
  instructions:
    "Each line is a merged PR: number | title | body excerpt. If all PRs share one specific engineering theme, return coherent=true with a short thematic label and one-sentence evidence-grounded summary (a and b may be empty: label '', summary '', prs []). Otherwise return coherent=false and split the set into two nonempty parts a and b along the strongest dividing concern, each with a label and summary. Every listed number must appear in exactly one part. Use only listed numbers.",
});

const clean = (t = "") => t.replace(/https?:\S+/g, "").replace(/\s+/g, " ").trim();
const MAX_CALLS = 34;

// Workflow role: top-down divisive clustering of merged PRs by recursive model bisection with TypeScript validation.
export default workflow({
  meta: {
    name: "divisive-recursive-bisection",
    description: "Recursively bisect the PR set until each part is judged coherent; TypeScript validates every split",
    phases: ["Bisect", "Validate"],
  },
  body: async ({ call, phase }) => {
    const corpus = JSON.parse(readFileSync("/tmp/gh-aw/agent/merged-prs.json", "utf8"));
    const prs: Pr[] = corpus.prs;
    const byNum = new Map(prs.map((p) => [p.number, p]));
    if (prs.length === 0 || byNum.size !== prs.length) throw new Error("bad corpus");
    const line = (n: number) => `${n} | ${byNum.get(n)!.title} | ${clean(byNum.get(n)!.body).slice(0, 220)}`;

    phase("Bisect");
    let queue: Node[] = [{ prs: prs.map((p) => p.number).sort((x, y) => x - y), label: "", summary: "" }];
    const done: Node[] = [];
    let calls = 0;
    while (queue.length > 0) {
      const small = queue.filter((n) => n.prs.length < 4);
      done.push(...small);
      const open = queue.filter((n) => n.prs.length >= 4);
      const batch = open.slice(0, Math.min(3, MAX_CALLS - calls));
      done.push(...open.slice(batch.length).filter(() => calls >= MAX_CALLS));
      const rest = calls >= MAX_CALLS ? [] : open.slice(batch.length);
      if (batch.length === 0) {
        queue = rest;
        if (calls >= MAX_CALLS) break;
        continue;
      }
      calls += batch.length;
      const res = await Promise.all(
        batch.map((n, i) => call(splitSet, { prs: n.prs.map(line).join("\n") }, { label: `split${calls}-${i}` })),
      );
      const next: Node[] = [];
      res.forEach((r, i) => {
        if (!r) throw new Error("missing split response");
        const node = batch[i];
        if (r.coherent) {
          if (!r.label.trim() || !r.summary.trim()) throw new Error("coherent set lacks label or summary");
          done.push({ prs: node.prs, label: r.label, summary: r.summary });
          return;
        }
        const all = [...r.a.prs, ...r.b.prs];
        const want = new Set(node.prs);
        if (r.a.prs.length === 0 || r.b.prs.length === 0) throw new Error("empty split part");
        if (all.length !== want.size || new Set(all).size !== all.length || all.some((n) => !want.has(n))) {
          throw new Error("split is not an exact partition of its input");
        }
        for (const x of [r.a, r.b]) {
          if (!x.label.trim() || !x.summary.trim()) throw new Error("part lacks label or summary");
          next.push({ prs: [...x.prs].sort((p, q) => p - q), label: x.label, summary: x.summary });
        }
      });
      queue = [...rest, ...next];
    }
    done.push(...queue);

    phase("Validate");
    const clusters = done
      .filter((n) => n.prs.length >= 2)
      .map((n) => ({
        id: `d${String(n.prs[0]).padStart(5, "0")}`,
        label: n.label || "Unlabeled",
        summary: n.summary,
        prs: n.prs,
        size: n.prs.length,
      }))
      .sort((x, y) => y.size - x.size || x.id.localeCompare(y.id));
    const unclassified = done
      .filter((n) => n.prs.length === 1)
      .map((n) => ({ pr: n.prs[0], reason: `Isolated by bisection as a singleton part (${n.label || "no label"})` }))
      .sort((x, y) => x.pr - y.pr);
    const seen = new Set<number>();
    for (const n of [...clusters.flatMap((c) => c.prs), ...unclassified.map((u) => u.pr)]) {
      if (!byNum.has(n) || seen.has(n)) throw new Error(`invalid or duplicate PR ${n}`);
      seen.add(n);
    }
    if (seen.size !== prs.length) throw new Error("incomplete coverage");
    if (new Set(clusters.map((c) => c.id)).size !== clusters.length) throw new Error("duplicate cluster id");

    return {
      repository: corpus.repository,
      window: corpus.window,
      strategy: "Divisive recursive bisection: model splits each PR set along its strongest fault line until judged coherent",
      totalPrs: prs.length,
      modelCalls: calls,
      clusters,
      topThree: clusters.slice(0, 3).map((c) => c.id),
      unclassified,
    };
  },
});
